css:
.entry { display: inline-flex; align-items: center; gap: 7px; margin-bottom: 10px; font-size: 11px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--text); background: rgba(240,191,0,.14); border: 1px solid rgba(240,191,0,.55); border-radius: 6px; padding: 4px 9px; }
.entry svg { width: 13px; height: 13px; flex: none; fill: var(--star); }
.entry-support { background: rgba(8,9,10,.6); border-color: var(--border-strong); }
.entry-support svg { fill: var(--text-2); }
